#!/usr/bin/env node
/**
 * Refresh the OpenRouter catalog fixtures used by the extension.
 *
 * The analyzer's resolveContextLength looks up model context lengths in
 * the live OpenRouter /models catalog first, then falls back to a
 * bundled subset. The bundled subset is regenerated by this script
 * and ships inside the .vsix so the analyzer works offline / on flaky
 * networks for the most common models.
 *
 * Outputs:
 *   - assets/openrouter-catalog.json     (top-N subset, bundled in .vsix)
 *   - tests/fixtures/openrouter-catalog.json (full catalog, test-only)
 *
 * The script requires `out/` to be built first (run `npm run compile`).
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');
const BUNDLED_FIXTURE = path.join(REPO_ROOT, 'assets', 'openrouter-catalog.json');
const TEST_FIXTURE = path.join(REPO_ROOT, 'tests', 'fixtures', 'openrouter-catalog.json');

// How many popular models to bundle. The full 1,215-entry catalog is
// ~250KB; bundling all of it is wasteful. The top N covers the vast
// majority of real-world usage for offline fallback. N is generous —
// adjust if the bundle size becomes a concern.
const BUNDLE_SIZE = 75;

// Self-bootstrap: if `out/` is missing (e.g. fresh checkout), build it
// first so the dynamic import below resolves.
const compiledPath = path.join(REPO_ROOT, 'out', 'modelCatalog.js');
if (!fs.existsSync(compiledPath)) {
  console.log('out/modelCatalog.js missing — running `npm run compile` first…');
  const { spawnSync } = await import('node:child_process');
  const result = spawnSync('npm', ['run', 'compile'], { cwd: REPO_ROOT, stdio: 'inherit' });
  if (result.status !== 0) {
    console.error('`npm run compile` failed; cannot refresh fixtures without compiled modelCatalog.js');
    process.exit(1);
  }
}

const modelCatalog = await import(path.join(REPO_ROOT, 'out', 'modelCatalog.js'));

console.log('Fetching live OpenRouter /models catalog...');
const t0 = Date.now();
const catalog = await modelCatalog.fetchContextLengths();
const elapsed = Date.now() - t0;

if (!catalog || catalog.size < 100) {
  console.error(
    `Refusing to refresh: catalog has only ${catalog?.size ?? 0} entries ` +
    '(expected >=100 — likely a fetch failure or stale cache).',
  );
  process.exit(1);
}

console.log(`Fetched ${catalog.size} entries in ${elapsed}ms`);

// Models we want in the bundled subset. Order matters: anything in this
// list is included even if the size cap is hit, and the order is
// preserved in the output for stable diffs. The list is curated for
// "models a real user would actually pick" — the long tail stays in
// the live catalog.
const FEATURED = [
  // OpenAI
  'openai/gpt-5', 'openai/gpt-5-mini', 'openai/gpt-5-nano',
  'openai/gpt-4.1', 'openai/gpt-4.1-mini', 'openai/gpt-4.1-nano',
  'openai/gpt-4o', 'openai/gpt-4o-mini',
  'openai/gpt-oss-120b', 'openai/gpt-oss-20b',
  'openai/o1', 'openai/o1-mini', 'openai/o3-mini', 'openai/o4-mini',
  // Anthropic
  'anthropic/claude-sonnet-4', 'anthropic/claude-sonnet-4.5', 'anthropic/claude-sonnet-4.6',
  'anthropic/claude-opus-4', 'anthropic/claude-opus-4.1', 'anthropic/claude-opus-4.5',
  'anthropic/claude-opus-4.6', 'anthropic/claude-opus-4.7',
  'anthropic/claude-haiku-4.5',
  // Google
  'google/gemini-2.5-pro', 'google/gemini-2.5-flash', 'google/gemini-2.5-flash-lite',
  'google/gemini-2.0-flash',
  'google/gemma-3-27b-it',
  // Meta
  'meta-llama/llama-3.1-8b-instruct', 'meta-llama/llama-3.3-70b-instruct',
  'meta-llama/llama-4-scout', 'meta-llama/llama-4-maverick',
  // Mistral
  'mistralai/mistral-large-2407', 'mistralai/mistral-small-2503',
  'mistralai/ministral-3b-2512', 'mistralai/mistral-nemo',
  'mistralai/codestral-2501',
  // DeepSeek
  'deepseek/deepseek-chat', 'deepseek/deepseek-chat-v3', 'deepseek/deepseek-r1',
  // Qwen
  'qwen/qwen-2.5-72b-instruct', 'qwen/qwen-2.5-coder-32b-instruct',
  'qwen/qwen3-coder-30b-a3b-instruct', 'qwen/qwen3-235b-a22b',
  // xAI
  'x-ai/grok-2', 'x-ai/grok-3', 'x-ai/grok-3-mini',
  // Cohere
  'cohere/command-r-plus', 'cohere/command-r',
  // NVIDIA
  'nvidia/llama-3.1-nemotron-70b-instruct', 'nvidia/nemotron-3-nano-30b-a3b',
  // Other
  'bytedance-seed/seed-1.6-flash',
];

const picked = new Map();
// First, add all featured models (order preserved)
for (const id of FEATURED) {
  if (catalog.has(id)) {
    picked.set(id, catalog.get(id));
  } else {
    // Try fuzzy match
    const base = id.split('/').pop();
    for (const [k, v] of catalog) {
      if (k.toLowerCase().includes(base.toLowerCase().slice(0, 25))) {
        picked.set(k, v);
        break;
      }
    }
  }
}

// Then pad with major-provider models up to BUNDLE_SIZE
const KEEP_PROVIDERS = [
  'openai/', 'anthropic/', 'google/', 'meta-llama/', 'mistralai/', 'deepseek/',
  'qwen/', 'x-ai/', 'cohere/', 'nvidia/',
];
for (const [k, v] of catalog) {
  if (picked.size >= BUNDLE_SIZE) break;
  if (!KEEP_PROVIDERS.some(p => k.startsWith(p))) continue;
  const lower = k.toLowerCase();
  // Skip non-canonical variants: free, nitro, dated snapshots
  if (lower.includes(':free') || lower.includes('nitro')) continue;
  // Skip dated variants like "-20250219" (keep the canonical name)
  if (/\-\d{8}$/.test(lower)) continue;
  if (!picked.has(k)) picked.set(k, v);
}

const sorted = Array.from(picked.entries()).sort(([a], [b]) => a.localeCompare(b));

// Write the bundled subset (runtime asset)
fs.mkdirSync(path.dirname(BUNDLED_FIXTURE), { recursive: true });
const bundled = {
  fetchedAt: new Date().toISOString(),
  count: picked.size,
  bundledSize: BUNDLE_SIZE,
  entries: sorted,
};
fs.writeFileSync(BUNDLED_FIXTURE, JSON.stringify(bundled, null, 2));
const bundledBytes = fs.statSync(BUNDLED_FIXTURE).size;

// Write the full catalog (test fixture, used for drift detection only)
fs.mkdirSync(path.dirname(TEST_FIXTURE), { recursive: true });
const full = {
  fetchedAt: new Date().toISOString(),
  count: catalog.size,
  entries: Array.from(catalog.entries()).sort(([a], [b]) => a.localeCompare(b)),
};
fs.writeFileSync(TEST_FIXTURE, JSON.stringify(full, null, 2));
const fullBytes = fs.statSync(TEST_FIXTURE).size;

console.log(`\nWrote ${picked.size}/${catalog.size} entries to ${path.relative(REPO_ROOT, BUNDLED_FIXTURE)} (${bundledBytes} bytes)`);
console.log(`Wrote ${catalog.size} entries to ${path.relative(REPO_ROOT, TEST_FIXTURE)} (${fullBytes} bytes, test-only)`);
console.log(`Bundle is ${(bundledBytes / fullBytes * 100).toFixed(1)}% the size of the full catalog`);
